Circle->{u8:radius}
Square->{u8:side}
Shape -> {
  circle -> Circle
  square -> Square
  -> circle:
  -> square:
}
None->{}
maybe -> {
  T -> None
  -> None:
  -> T:
}
double -> {
  maybe{Shape}:shape
  -> shape ? {
    None -> shape
    Circle -> shape{radius->.radius*2}
    Square -> shape{side->.side*2}
  }
}
